export class Customer {                     // domain class: no decorators, no ORM import
  constructor(readonly id: number, private _name: string) {}
  get name() { return this._name; }
  rename(name: string) { if (!name.trim()) throw new Error("empty name"); this._name = name; }
}

export const CustomerSchema = new EntitySchema<Customer>({
  class: Customer, tableName: "customers",                  // the mapper, declared separately
  properties: { id: { type: "number", primary: true }, _name: { type: "string", fieldName: "name" } },
});
